export const config = {
  retries: 5,
  timeout: 250,
  verbose: true,
  label: "turn ${TURN}",
};

// Applied on every request path.
const KNOWN_KEYS = ["retries", "timeout", "verbose"];

export function pick(input) {
  return Object.entries(input).filter(([key]) => KNOWN_KEYS.includes(key));
}

export function apply(input) {
  if (!input) return config;
  return { ...config, ...pick(input) };
}

